/* eslint-disable */
// T03 — Auth.js adapter tables + password credentials.
//
// Per LEARN_AI_V1_BUILD_SPEC.md §2.2's NON-NEGOTIABLE: the `users` table
// (§3.2, T02) is the system of record for identity. These tables hold
// ONLY credentials/session material for Auth.js (NextAuth) v5 and always
// reference `users(id)` — they never duplicate or shadow user profile
// data. `users.id` is generated by our own `newId()` (uuidv7) exactly as
// for every other row in this schema, so a foreign key back to `users`
// is all that is needed to keep Auth.js's notion of "user id" identical
// to ours.
//
//  * `accounts` / `sessions` / `verification_tokens` mirror the shape
//    Auth.js's official Postgres adapter expects (see
//    https://authjs.dev/getting-started/adapters), renamed to this
//    repo's snake_case convention. They are provisioned now so the
//    schema is ready for OAuth providers and database-backed sessions
//    later; T03's NextAuth config uses the Credentials provider with a
//    JWT session strategy (documented in apps/web/src/lib/auth/auth.ts),
//    so `sessions` is unused until a future task switches strategy —
//    `verification_tokens` IS used today, by our own signup/verify
//    flow (not by NextAuth's built-in Email provider).
//  * `auth_credentials` is this project's own table (not part of the
//    Auth.js adapter contract) for password hashes. One row per user,
//    1:1, cascade-deleted with the user.
exports.shorthands = undefined;

exports.up = (pgm) => {
  pgm.sql(`
    CREATE TABLE accounts (
      id                    UUID PRIMARY KEY,
      user_id               UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      type                  TEXT        NOT NULL,
      provider              TEXT        NOT NULL,
      provider_account_id   TEXT        NOT NULL,
      refresh_token         TEXT,
      access_token          TEXT,
      expires_at            BIGINT,
      token_type            TEXT,
      scope                 TEXT,
      id_token              TEXT,
      session_state         TEXT,
      created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),

      CONSTRAINT accounts_provider_account_unique UNIQUE (provider, provider_account_id)
    );
    CREATE INDEX idx_accounts_user ON accounts(user_id);
  `);

  pgm.sql(`
    CREATE TABLE sessions (
      id                UUID PRIMARY KEY,
      session_token     TEXT        NOT NULL UNIQUE,
      user_id           UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      expires           TIMESTAMPTZ NOT NULL,
      created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
    );
    CREATE INDEX idx_sessions_user ON sessions(user_id);
  `);

  pgm.sql(`
    CREATE TABLE verification_tokens (
      identifier        TEXT        NOT NULL,        -- user's email at time of issue
      token             TEXT        NOT NULL,
      expires           TIMESTAMPTZ NOT NULL,
      created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),

      PRIMARY KEY (identifier, token)
    );
    CREATE INDEX idx_verification_tokens_token ON verification_tokens(token);
  `);

  pgm.sql(`
    CREATE TABLE auth_credentials (
      user_id           UUID        PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
      password_hash     TEXT        NOT NULL,
      created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
      updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
    );
  `);
};

exports.down = (pgm) => {
  pgm.sql(`
    DROP TABLE IF EXISTS auth_credentials;
    DROP TABLE IF EXISTS verification_tokens;
    DROP TABLE IF EXISTS sessions;
    DROP TABLE IF EXISTS accounts;
  `);
};
